/**
 * frontend/src/components/CameraRecognition.jsx
 * Version simplifiée et corrigée - Focus sur la stabilité de la caméra
 */

import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);

  const [cameraActive, setCameraActive] = useState(false);
  const [autoMode, setAutoMode] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const [lastResult, setLastResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);

  // ====================== DÉMARRAGE CAMÉRA ======================
  const startCamera = async () => {
    try {
      setError(null);
      setLoading(true);

      console.log('[CAMERA] Demande d\'accès à la webcam...');

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user" }
      });

      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;

        videoRef.current.onloadedmetadata = async () => {
          console.log('[CAMERA] Vidéo prête');
          setCameraActive(true);
          setLoading(false);

          try {
            await videoRef.current.play();
            console.log('[CAMERA] Lecture démarrée avec succès');
          } catch (playErr) {
            console.warn('[CAMERA] Erreur play:', playErr);
          }

          setAutoMode(true);
          startCaptureLoop();
        };
      }
    } catch (err) {
      console.error('[CAMERA] Erreur getUserMedia:', err);

      let errorMsg = "Impossible d'accéder à la caméra";

      if (err.name === 'NotAllowedError') {
        errorMsg = "Permission caméra refusée. Veuillez autoriser l'accès.";
      } else if (err.name === 'NotFoundError') {
        errorMsg = "Aucune caméra détectée sur cet appareil.";
      } else if (err.name === 'NotReadableError') {
        errorMsg = "Caméra déjà utilisée par une autre application.";
      }

      setError(errorMsg);
      setLoading(false);

      if (addNotification) {
        addNotification(errorMsg, 'error');
      }
    }
  };

  // ====================== BOUCLE DE CAPTURE ======================
  const startCaptureLoop = () => {
    console.log('[CAPTURE] Boucle démarrée');

    const captureFrame = async () => {
      if (!videoRef.current) return;

      try {
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 640;
        canvas.height = videoRef.current.videoHeight || 480;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.8);
        const base64Data = imageBase64.split(',')[1];

        const response = await attendanceAPI.recognize(base64Data);
        const data = response?.data;

        if (data?.success && data.student) {
          setLastResult(data);
          setCapturedImage(imageBase64);
          if (addNotification) {
            addNotification(`${data.student} détecté`, 'success');
          }
        }
      } catch (err) {
        console.warn('[CAPTURE] Erreur:', err.message);
      }
    };

    // Lancer la boucle toutes les 1000ms
    setInterval(captureFrame, 1000);
  };

  // ====================== ARRÊT CAMÉRA ======================
  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setCameraActive(false);
    setAutoMode(false);
    setError(null);
  };

  // Nettoyage au démontage
  useEffect(() => {
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Reconnaissance Faciale</h1>

      <div style={styles.videoContainer}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={styles.video}
        />

        {cameraActive && (
          <div style={styles.statusBadge}>
            Caméra active - Scan en cours
          </div>
        )}
      </div>

      <div style={styles.controls}>
        {!cameraActive ? (
          <button 
            onClick={startCamera} 
            disabled={loading}
            style={styles.btnPrimary}
          >
            {loading ? 'Démarrage...' : 'Démarrer la caméra'}
          </button>
        ) : (
          <>
            <button onClick={stopCamera} style={styles.btnDanger}>
              Arrêter la caméra
            </button>
          </>
        )}
      </div>

      {error && (
        <div style={styles.errorBox}>
          {error}
        </div>
      )}

      {lastResult && (
        <div style={styles.resultBox}>
          <h3>✅ {lastResult.student} détecté</h3>
          <p>Confiance : {(lastResult.confidence * 100).toFixed(1)}%</p>
        </div>
      )}
    </div>
  );
};

const styles = {
  container: {
    padding: '30px',
    maxWidth: '900px',
    margin: '0 auto',
    fontFamily: 'system-ui, Arial, sans-serif'
  },
  title: {
    textAlign: 'center',
    fontSize: '1.8rem',
    marginBottom: '25px'
  },
  videoContainer: {
    position: 'relative',
    backgroundColor: '#000',
    borderRadius: '12px',
    overflow: 'hidden',
    marginBottom: '20px',
    boxShadow: '0 4px 15px rgba(0,0,0,0.2)'
  },
  video: {
    width: '100%',
    display: 'block'
  },
  statusBadge: {
    position: 'absolute',
    top: '15px',
    right: '15px',
    backgroundColor: '#10B981',
    color: 'white',
    padding: '8px 16px',
    borderRadius: '20px',
    fontSize: '0.9rem',
    fontWeight: '600'
  },
  controls: {
    display: 'flex',
    gap: '12px',
    marginBottom: '20px'
  },
  btnPrimary: {
    flex: 1,
    padding: '14px',
    backgroundColor: '#4F46E5',
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    fontWeight: '600',
    cursor: 'pointer'
  },
  btnDanger: {
    flex: 1,
    padding: '14px',
    backgroundColor: '#EF4444',
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    fontWeight: '600',
    cursor: 'pointer'
  },
  errorBox: {
    padding: '16px',
    backgroundColor: '#FEE2E2',
    color: '#991B1B',
    borderRadius: '8px',
    marginBottom: '20px'
  },
  resultBox: {
    padding: '20px',
    backgroundColor: '#F0FDF4',
    borderRadius: '8px',
    borderLeft: '5px solid #10B981'
  }
};

export default CameraRecognition;
